import tokens from "../tokens.json" with { type: "json" };
import { toCss } from "./color.ts";

const HEADER = "generated by packages/ui-tokens (pnpm --filter @openphysio/ui-tokens gen) from tokens.json, do not edit";
const camel = (s: string) => s.replace(/-(\w)/g, (_, c: string) => c.toUpperCase());
const json = (v: unknown) => JSON.stringify(v, null, 2);

/** The two generated files, as text. Pure, so a test can compare against the committed copies. */
export function build() {
  const block = (mode: "light" | "dark") =>
    Object.entries(tokens.color[mode])
      .map(([k, v]) => `      --color-${k}: ${v};`)
      .join("\n");
  const css = `/* ${HEADER} */
@import "tailwindcss";
@import "uniwind";
@import "tw-animate-css";

@theme {
  --radius: ${tokens.radius.base}px;
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
  --spacing-hairline: hairlineWidth();
}

@layer theme {
  :root {
    @variant light {
${block("light")}
    }

    @variant dark {
${block("dark")}
    }
  }
}
`;
  const colors = (mode: "light" | "dark") =>
    Object.fromEntries(Object.entries(tokens.color[mode]).map(([k, v]) => [camel(k), toCss(v)]));
  const ts = `// ${HEADER}
// sRGB values for SVG, charts and RN styles that cannot take a class.

export const colors = ${json({ light: colors("light"), dark: colors("dark") })} as const;

/** Session-type colours, handed out in order. */
export const sessionTypeColors = ${json({ light: tokens.sessionType.light.map(toCss), dark: tokens.sessionType.dark.map(toCss) })} as const;

export const spacing = ${json(tokens.spacing)} as const;
export const fontSize = ${json(tokens.fontSize)} as const;
export const radius = ${json(tokens.radius)} as const;
export const duration = ${json(tokens.duration)} as const;

export type Theme = "light" | "dark";
`;
  return { css, ts };
}
